// Borrowing transfers a real parent pin, never just a copied MHW address. The
// enclosing owner must attest the exact VPHAL/OS/image-generation association;
// a native context's removal status alone cannot supply that association.
template<class ParentLease> class TglNativeBorrowedVphalMhwLease {
    ParentLease parent_;
    TglNativeVphalMhwView view_;
public:
    TglNativeBorrowedVphalMhwLease()=default;
    TglNativeBorrowedVphalMhwLease(const TglNativeBorrowedVphalMhwLease&)=delete;
    TglNativeBorrowedVphalMhwLease& operator=(const TglNativeBorrowedVphalMhwLease&)=delete;
    // Allows binding/backing construction BEFORE transferring this SAME pin
    // into a stable frame. Never overwrite a live dependency or reacquire it.
    bool transferFrom(TglNativeBorrowedVphalMhwLease&& other) noexcept {
        static_assert(std::is_nothrow_move_assignable_v<ParentLease>);
        if(this==&other || parent_.get() || !other.parent_.get()) return false;
        parent_=std::move(other.parent_);view_=other.view_;other.view_={};return true;
    }
    template<class Read,class Admit,class Qualify,class Executable,class ParentAdmit>
    bool acquire(ParentLease&& parent,uintptr_t image,uintptr_t vphal,uintptr_t creator,
        Read read,Admit admit,Qualify qualify,Executable executable,ParentAdmit parentAdmit) noexcept {
        static_assert(std::is_nothrow_move_assignable_v<ParentLease>);
        if(parent_.get() || !parent.get()) return false;
        TglNativeVphalMhwView candidate;
        if(!candidate.resolve(image,vphal,creator,read,admit,qualify,executable) ||
            !parentAdmit(*parent.get(),candidate)) return false;
        parent_=std::move(parent);view_=candidate;return true;
    }
    template<class Lifetime,class Read,class Admit,class Qualify,class Executable,class ParentAdmit>
    bool acquireOwned(ParentLease&& parent,uintptr_t image,uintptr_t vphal,uintptr_t creator,
        const Lifetime& lifetime,Read read,Admit admit,Qualify qualify,Executable executable,ParentAdmit parentAdmit) noexcept {
        static_assert(std::is_nothrow_move_assignable_v<ParentLease>);
        if(parent_.get() || !parent.get()) return false;
        TglNativeVphalMhwView candidate;
        if(!candidate.resolveOwned(image,vphal,creator,lifetime,read,admit,qualify,executable) ||
            !parentAdmit(*parent.get(),candidate)) return false;
        parent_=std::move(parent);view_=candidate;return true;
    }
    const TglVeboxHardwareBinding* binding() const noexcept {
        return parent_.get()?&view_.hardware:nullptr;
    }
    const TglNativeVphalMhwView* view() const noexcept {
        return parent_.get()?&view_:nullptr;
    }
    template<class Use> int withParentLease(Use use) const noexcept {
        static_assert(std::is_nothrow_invocable_r_v<int,Use&,const ParentLease&,const TglNativeVphalMhwView&>);
        if(!parent_.get())return 5;
        return use(std::as_const(parent_),std::as_const(view_));
    }
    // Default destruction releases ONLY the parent pin. The original native
    // VPHAL remains sole MHW owner; no heap cleanup/delete is performed here.
};

// Retained by the context registry, which must quarantine rather than destroy
// an owner with a live allocation/lease. No destructor-side native deletion:
// unproven GPU retirement must never become a free through stack unwinding.
template<class Invoke=TglNativeVeboxMhwAllocationInvoker> class TglNativeVeboxMhwOwner {
    TglNativeVeboxMhwAllocationBinding allocation_{};
    TglVeboxHardwareBinding hardware_{};
    Invoke& invoke_;
    uintptr_t object_=0,os_=0;
    uint64_t generation_=0;
    bool busy_=false,pinned_=false,ready_=false;
    struct Unlock {bool& flag;~Unlock(){flag=false;}};
public:
    explicit TglNativeVeboxMhwOwner(Invoke& invoke):invoke_(invoke){}
    TglNativeVeboxMhwOwner(const TglNativeVeboxMhwOwner&)=delete;
    TglNativeVeboxMhwOwner& operator=(const TglNativeVeboxMhwOwner&)=delete;
    bool empty() const noexcept {return !object_;}
    uint64_t generation() const noexcept {return generation_;}
    template<class Read,class Qualify,class Executable>
    uint32_t initialize(const TglNativeVeboxMhwAllocationBinding& binding,uintptr_t os,
                        Read read,Qualify qualify,Executable executable) {
        if(busy_ || pinned_ || object_ || !os || generation_==UINT64_MAX) return 5;
        TglNativeVeboxMhwAllocationBinding verified;
        if(!verified.resolve(binding.image,read,qualify,executable) ||
           verified.create!=binding.create || verified.remove!=binding.remove) return 5;
        busy_=true;Unlock unlock{busy_};
        allocation_=verified;os_=os;++generation_;
        object_=invoke_.create(allocation_.create,os);
        if(!object_) {allocation_={};os_=0;return 5;}
        const auto result=hardware_.initializeHeap(object_,os,allocation_.image,read,qualify,
            executable,[&](uintptr_t entry,uintptr_t object){return invoke_.heap(entry,object);});
        ready_=result==0;
        return result; // even failure retains factory provenance for explicit teardown
    }
    class DependencyLease {
        TglNativeVeboxMhwOwner* owner_=nullptr;
        uint64_t generation_=0;
    public:
        DependencyLease()=default;
        explicit DependencyLease(TglNativeVeboxMhwOwner& owner) noexcept {acquire(owner);}
        bool acquire(TglNativeVeboxMhwOwner& owner) noexcept {
            if(owner_ || owner.busy_ || owner.pinned_ || !owner.ready_) return false;
            owner.pinned_=true;owner_=&owner;generation_=owner.generation_;
            return true;
        }
        DependencyLease(const DependencyLease&)=delete;
        DependencyLease& operator=(const DependencyLease&)=delete;
        ~DependencyLease(){if(owner_) owner_->pinned_=false;}
        const TglVeboxHardwareBinding* binding() const noexcept {
            return owner_ && owner_->pinned_ && owner_->ready_ &&
                owner_->generation_==generation_ ? &owner_->hardware_:nullptr;
        }
    };
    template<class Read,class Qualify,class Executable,class Retired>
    uint32_t retire(Read read,Qualify qualify,Executable executable,Retired retired) {
        if(busy_ || pinned_ || !object_) return 5;
        busy_=true;Unlock unlock{busy_};
        uintptr_t vt=0,actualOs=0,heap=0,deleting=0;
        const auto image=allocation_.image;
        TglNativeVeboxMhwAllocationBinding verified;
        if(!verified.resolve(image,read,qualify,executable) ||
            verified.create!=allocation_.create || verified.remove!=allocation_.remove) return 5;
        if(object_>UINTPTR_MAX-0x28 || !qualify(image) ||
           !read(object_,&vt,8) || vt!=image+0x759520 ||
           !read(object_+0x18,&actualOs,8) || actualOs!=os_ ||
           !read(object_+0x20,&heap,8) ||
           !read(image+0x759528,&deleting,8) || deleting!=image+0x179d10 ||
           !retired(object_,os_,heap,generation_)) return 5;
        uintptr_t afterVt=0,afterOs=0,afterHeap=0;
        if(!read(object_,&afterVt,8) || afterVt!=vt ||
           !read(object_+0x18,&afterOs,8) || afterOs!=actualOs ||
           !read(object_+0x20,&afterHeap,8) || afterHeap!=heap) return 5;
        if(heap) {
            TglVeboxHardwareBinding current;
            if(!current.resolve(object_,os_,image,read,qualify) || current.heap!=heap) return 5;
            const auto result=current.releaseRetiredHeap(image,read,qualify,executable,
                [&](uintptr_t object,uintptr_t os,uintptr_t h){return object==object_ && os==os_ && h==heap;},
                [&](uintptr_t entry,uintptr_t object){return invoke_.heap(entry,object);});
            if(result) return result;
        }
        ready_=false;hardware_={};
        invoke_.remove(allocation_.remove,object_);
        if(object_) return 5;
        allocation_={};os_=0;return 0;
    }
};

// Complete native G12 MHW lifetime for externally owned, stable storage.
// Enclosing owner retains storage/OS/image and serializes all operations;
// no native factory accounting/deleting destructor is used for this storage.
struct TglVeboxMhwLifetimeBinding {
    uintptr_t image=0,construct=0,destroy=0;
    template<class Read,class Qualify,class Executable>
    bool resolve(uintptr_t base,Read read,Qualify qualify,Executable executable) {
        *this={};
        constexpr std::array<uint8_t,16> ctor{
            0x55,0x48,0x89,0xe5,0x48,0x83,0xec,0x40,
            0x48,0x89,0x7d,0xf8,0x48,0x89,0x75,0xf0};
        constexpr std::array<uint8_t,16> dtor{
            0x55,0x48,0x89,0xe5,0x48,0x83,0xec,0x10,
            0x48,0x89,0x7d,0xf8,0x48,0x8b,0x7d,0xf8};
        auto c=ctor,d=dtor;
        if(!base || base>UINTPTR_MAX-0x759528 || !qualify(base) ||
           !executable(base+0x16f140,16) || !executable(base+0x179cf0,16) ||
           !read(base+0x16f140,c.data(),16) || c!=ctor ||
           !read(base+0x179cf0,d.data(),16) || d!=dtor) return false;
        image=base;construct=base+0x16f140;destroy=base+0x179cf0;
        return true;
    }
    template<class Invoke>
    bool constructStorage(void* storage,size_t extent,uintptr_t os,Invoke invoke) const {
        const auto p=reinterpret_cast<uintptr_t>(storage);
        if(!image || construct!=image+0x16f140 || !storage || (p&7) ||
           extent!=TglVeboxHardwareBinding::objectExtent ||
           p>UINTPTR_MAX-extent || !os || os>UINTPTR_MAX-0x1c0) return false;
        // Reject re-construction before native can overwrite a live heap/OS.
        // Owned allocation is zero-initialized; native factory memory need not
        // be, and is intentionally not admitted through this owned entry.
        auto* bytes=static_cast<uint8_t*>(storage);
        for(size_t i=0;i<extent;++i) if(bytes[i]) return false;
        invoke(construct,storage,os);
        uintptr_t vt=0,actualOs=0,heap=0;
        std::memcpy(&vt,bytes,8);std::memcpy(&actualOs,bytes+0x18,8);
        std::memcpy(&heap,bytes+0x20,8);
        return vt==image+0x759520 && actualOs==os && !heap;
    }
    template<class Invoke>
    bool destroyHeapFreeStorage(void* storage,size_t extent,Invoke invoke) const {
        const auto p=reinterpret_cast<uintptr_t>(storage);
        if(!image || destroy!=image+0x179cf0 || !storage || (p&7) ||
           extent!=TglVeboxHardwareBinding::objectExtent || p>UINTPTR_MAX-extent) return false;
        uintptr_t vt=0,heap=0;
        auto* bytes=static_cast<uint8_t*>(storage);
        std::memcpy(&vt,bytes,8);std::memcpy(&heap,bytes+0x20,8);
        if(vt!=image+0x759520 || heap) return false;
        // Caller has detached all consumers; heap retirement occurs BEFORE here.
        invoke(destroy,storage);return true;
    }
};

