    const TglOwnedGen12SurfaceFeatures targetFeatures_;
    void* lutScope_=nullptr;
    bool(*lutProduce_)(void*,TglOwnedGen12SurfaceFeatures&) noexcept=nullptr;
    bool lutAttempted_=false;
