    const bool sameFormat=tables.format==format;
    const bool reuseX=sameFormat && (tables.scaleX==scaleX ||
        (tables.scaleX>1.f && scaleX>1.f));
    const bool reuseY=sameFormat && (tables.scaleY==scaleY ||
        (tables.scaleY>1.f && scaleY>1.f));
