    uint32_t type=0,format=0;
    uintptr_t handle=0;
    std::memcpy(&type,resource.data()+0x14,4);
    std::memcpy(&format,resource.data()+0x18,4);
    std::memcpy(&handle,resource.data()+0x58,8);
