        if(!current.capture(TglNativeFrameOutputReceipt{context_,event_,index_,true},batch_,read) ||
            current.count_!=count_ || current.list_!=list_ || current.item_!=item_ ||
            current.type_!=type_ || current.wait_!=wait_) return false;
